//! The Autonomy Charter as code (brief C11 §1–§7): one test per rule. Several rules are about what
//! does *not* exist (no admin path, no holder vote, no personal data); those are pinned by auditing
//! the program surface in the IDLs generated by the same `anchor build` that produced the tested
//! `.so` files, against reviewed snapshots in `tests/fixtures`.

use std::collections::{BTreeMap, BTreeSet};

use anchor_lang::prelude::Pubkey;
use merces_common::time::DAY;
use merces_common::treasury::tranche_amount;
use merces_protocol::error::ProtocolError;
use merces_registry::error::RegistryError;
use merces_tests::harness::*;
use merces_tests::vectors::{run_vector, Runner};
use merces_tests::zkfix::vector_path;
use serde_json::{json, Value};
use solana_signer::Signer;

fn vector(name: &str) -> Value {
    serde_json::from_str(&std::fs::read_to_string(vector_path(name)).unwrap()).unwrap()
}

fn idl(program: &str) -> Value {
    let path = format!(
        "{}/../target/idl/{program}.json",
        env!("CARGO_MANIFEST_DIR")
    );
    serde_json::from_str(&std::fs::read_to_string(path).expect("IDL (run anchor build)")).unwrap()
}

fn assert_code(res: Result<(), String>, code: u32, what: &str) {
    match res {
        Ok(()) => panic!("{what}: expected error {code}, call succeeded"),
        Err(msg) => assert!(
            msg.contains(&format!("Custom({code})")),
            "{what}: expected {code}, got {msg}"
        ),
    }
}

fn expect_code(res: TxResult, code: u32, what: &str) {
    assert_code(
        res.map(|_| ())
            .map_err(|f| format!("{:?}\n{}", f.err, f.meta.logs.join("\n"))),
        code,
        what,
    );
}

/// Index of the first step with `op` (after `from`).
fn step_index(v: &Value, op: &str, from: usize) -> usize {
    v["steps"].as_array().unwrap()[from..]
        .iter()
        .position(|s| s["op"] == op)
        .map(|i| i + from)
        .unwrap_or_else(|| panic!("no {op} step"))
}

/// C11 §1: capital releases follow the fixed schedule with no approval from anyone; only the Late
/// status and the issuer's own request pause them.
#[test]
fn c11_1_releases_follow_the_schedule_without_approval() {
    let v = vector("01_happy_path.json");
    let settled = step_index(&v, "claim_release", 0) - 1;
    let mut r = Runner::run_value(v.clone(), Some(settled));
    let s1 = r.series_pubkey("S1").unwrap();
    let issuer = r.actor_keypair("issuer");
    let admin = r.env.admin.insecure_clone();
    let keeper = r.env.new_wallet();
    let s = r.env.series(&s1);
    let schedule: Vec<_> = s
        .release_schedule
        .iter()
        .map(|t| merces_common::params::Tranche::from(*t))
        .collect();
    let t = r.env.treasury(&s1).unwrap();
    let settlement = r.env.ledger(&s1).unwrap().settlement_ts;
    r.env.warp(settlement + schedule[0].at_offset_seconds);
    // nobody but the issuer, and nobody's approval: the vested tranche simply pays out
    for other in [&admin, &keeper] {
        expect_code(
            r.env.claim_release(other, &s1),
            u32::from(ProtocolError::NotIssuer),
            "third party release",
        );
        expect_code(
            r.env.set_release_pause(other, &s1, true),
            u32::from(ProtocolError::NotIssuer),
            "third party pause",
        );
    }
    let usdc = r.env.usdc;
    let before = r.env.balance_of(&issuer.pubkey(), &usdc);
    r.env.claim_release(&issuer, &s1).unwrap();
    let first = tranche_amount(t.proceeds, &schedule, 0).unwrap();
    assert_eq!(r.env.balance_of(&issuer.pubkey(), &usdc), before + first);
    // the issuer's own request pauses releases; lifting it restores them
    r.env.warp(settlement + schedule[1].at_offset_seconds);
    r.env.set_release_pause(&issuer, &s1, true).unwrap();
    expect_code(
        r.env.claim_release(&issuer, &s1),
        u32::from(ProtocolError::ReleasesPausedByIssuer),
        "issuer pause",
    );
    r.env.set_release_pause(&issuer, &s1, false).unwrap();
    r.env.claim_release(&issuer, &s1).unwrap();
    // Late blocks releases until the issuer is current (07); a hardship pause does not stop them
    // (08) but does not lift a block already in force (19). The vectors assert each transition.
    for (name, blocked) in [
        ("07_late_payment.json", true),
        ("08_hardship_pause.json", false),
        ("19_pause_while_late.json", true),
    ] {
        let v = vector(name);
        let steps = v["steps"].as_array().unwrap();
        let reverts = steps
            .iter()
            .any(|s| s["op"] == "expect_revert" && s["call"]["op"] == "claim_release");
        let releases = steps.iter().any(|s| s["op"] == "claim_release");
        assert!(releases && reverts == blocked, "{name}");
        run_vector(name);
    }
}

/// C11 §2: on-chain data about an issuer is limited to series parameters, the terms commitment,
/// payment amounts, statuses and events. Every account field of every program is pinned by a
/// reviewed snapshot (`tests/fixtures/onchain_fields.json`), and no field name may suggest personal
/// data.
#[test]
fn c11_2_onchain_data_is_limited_to_series_data() {
    let mut actual: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for prog in ["merces_registry", "merces_protocol", "merces_hook"] {
        let d = idl(prog);
        let types: BTreeMap<String, Value> = d["types"]
            .as_array()
            .map(|a| {
                a.iter()
                    .map(|t| (t["name"].as_str().unwrap().to_string(), t.clone()))
                    .collect()
            })
            .unwrap_or_default();
        for acc in d["accounts"].as_array().cloned().unwrap_or_default() {
            let name = acc["name"].as_str().unwrap();
            let fields = types[name]["type"]["fields"]
                .as_array()
                .unwrap()
                .iter()
                .map(|f| f["name"].as_str().unwrap().to_string())
                .collect();
            actual.insert(format!("{prog}::{name}"), fields);
        }
    }
    let path = format!(
        "{}/fixtures/onchain_fields.json",
        env!("CARGO_MANIFEST_DIR")
    );
    let expected: BTreeMap<String, Vec<String>> =
        serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    assert_eq!(
        actual, expected,
        "account fields changed: review against C11 §2 and update tests/fixtures/onchain_fields.json"
    );
    const FORBIDDEN: [&str; 16] = [
        "health",
        "medical",
        "diagnosis",
        "disability",
        "location",
        "country",
        "relationship",
        "spouse",
        "marital",
        "career",
        "employer",
        "job",
        "birth",
        "gender",
        "religion",
        "ethnicity",
    ];
    for (acc, fields) in &actual {
        for f in fields {
            assert!(
                !f.split('_').any(|tok| FORBIDDEN.contains(&tok)),
                "{acc}.{f} looks like personal data"
            );
            // income itself never goes on chain: only commitments to it
            if f.contains("income") {
                assert!(
                    f.contains("commitment") || f.contains("period"),
                    "{acc}.{f}"
                );
            }
        }
    }
}

/// C11 §3: no work obligation — a zero report is a complete report with no penalty, and no function
/// can pull a payment from the issuer: `pay` only spends the signer's own stablecoin.
#[test]
fn c11_3_no_work_obligation() {
    let v = vector("01_happy_path.json");
    let first_report = step_index(&v, "submit_report", 0);
    let r = Runner::run_value(v.clone(), Some(first_report));
    let s1 = r.series_pubkey("S1").unwrap();
    let report = &v["steps"][first_report];
    assert_eq!(report["paymentUsd"], "0", "the first report pays nothing");
    let period: u32 = report["period"].as_str().unwrap().parse().unwrap();
    let l = r.env.ledger(&s1).unwrap();
    assert_eq!(l.last_paid_period(), Some(period));
    assert_eq!(l.open_due_amount, 0);
    assert_eq!(l.derived_status(r.env.now).unwrap() as u8, 0, "OnTime");
    // a whole year below θ (vector 04) never accrues anything and never turns Late
    run_vector("04_zero_quarters.json");
    // a keeper cannot make the issuer pay: `payer_stable` must belong to the signing payer
    let v = vector("01_happy_path.json");
    let due_report = v["steps"]
        .as_array()
        .unwrap()
        .iter()
        .enumerate()
        .position(|(i, s)| {
            s["op"] == "submit_report" && s["paymentUsd"] != "0" && v["steps"][i + 1]["op"] == "pay"
        })
        .unwrap();
    let mut r = Runner::run_value(v.clone(), Some(due_report));
    let s1 = r.series_pubkey("S1").unwrap();
    assert!(r.env.ledger(&s1).unwrap().open_due_amount > 0);
    let keeper = r.env.new_wallet();
    let issuer = r.actor_pubkey("issuer").unwrap();
    let usdc = r.env.usdc;
    let keeper_ata = r.env.create_ata(&keeper.pubkey(), &usdc);
    let issuer_ata = r.env.ata_of(&issuer, &usdc);
    let period = r.env.ledger(&s1).unwrap().open_due_period();
    let mut ixs = r.env.pay_ixs(&keeper.pubkey(), &s1, period, false);
    let pay = ixs.last_mut().unwrap();
    for meta in pay.accounts.iter_mut() {
        if meta.pubkey == keeper_ata {
            meta.pubkey = issuer_ata;
        }
    }
    let before = r.env.balance_of(&issuer, &usdc);
    let res = r.env.send(&ixs, &[&keeper]);
    assert!(
        res.is_err(),
        "a keeper cannot spend the issuer's stablecoin"
    );
    assert_eq!(r.env.balance_of(&issuer, &usdc), before);
}

/// C11 §4: units carry no vote. No instruction takes a holder signature except the holder's own
/// order book actions, and nothing that affects an issuer is signed by anyone but the issuer, an
/// attestor (off-chain signature over a nonce) or a permissionless payer.
#[test]
fn c11_4_units_carry_no_vote() {
    let allowed_signers: BTreeSet<&str> = [
        "admin",
        "pending_admin",
        "allowlist_manager",
        "issuer",
        "issuer_wallet",
        "payer",
        "keeper",
        "bidder",
        "owner",
        "approver",
        "mint_authority",
        "protocol_authority",
    ]
    .into_iter()
    .collect();
    // instructions a holder signs, all about the holder's own escrowed order or (curve mode) the
    // holder's own units: staking them to earn, unstaking, tendering them at redemption
    let holder_signed: BTreeSet<&str> = [
        "commit_bid",
        "reveal_bid",
        "commit_ask",
        "window_commit_bid",
        "reveal_order",
        "stake_units",
        "unstake_units",
        "tender_units",
    ]
    .into_iter()
    .collect();
    for prog in ["merces_registry", "merces_protocol", "merces_hook"] {
        for ix in idl(prog)["instructions"].as_array().unwrap() {
            let name = ix["name"].as_str().unwrap();
            let signers: Vec<&str> = ix["accounts"]
                .as_array()
                .unwrap()
                .iter()
                .filter(|a| a["signer"].as_bool().unwrap_or(false))
                .map(|a| a["name"].as_str().unwrap())
                .collect();
            for sgn in &signers {
                assert!(
                    allowed_signers.contains(sgn),
                    "{prog}::{name} takes an unexpected signer {sgn}"
                );
                if *sgn == "bidder" || *sgn == "owner" {
                    assert!(
                        holder_signed.contains(name),
                        "{prog}::{name} is signed by a holder"
                    );
                }
            }
            // the early-draw approver is the only co-signer next to an issuer
            if signers.contains(&"approver") {
                assert_eq!(name, "request_early_draw");
            }
        }
    }
}

/// C11 §5: the issuer can stop new issuance at any time; existing series end only through the cap,
/// redemption or extinguishment.
#[test]
fn c11_5_issuer_controls_new_issuance() {
    let mut env = Env::new();
    let issuer = env.new_wallet();
    let usdc = env.usdc;
    let existing = env.setup_series(&issuer, &usdc, Env::default_series_args([4u8; 32]));
    env.stop_issuance(&issuer).unwrap();
    let (res, _) = env.create_series_tx(&issuer, &usdc, None, Env::default_series_args([5u8; 32]));
    expect_code(
        res,
        u32::from(RegistryError::IssuanceStopped),
        "stopped issuance",
    );
    // the existing series is untouched: its raise still opens
    env.open_raise(&issuer, &existing).unwrap();
    env.resume_issuance(&issuer).unwrap();
    env.create_series(&issuer, &usdc, Env::default_series_args([5u8; 32]));
    // deactivation by the admin also blocks new series only
    env.deactivate_issuer(&issuer.pubkey()).unwrap();
    let (res, _) = env.create_series_tx(&issuer, &usdc, None, Env::default_series_args([6u8; 32]));
    expect_code(
        res,
        u32::from(RegistryError::IssuerInactive),
        "deactivated issuer",
    );
    env.cancel_raise(&issuer, &existing).unwrap();
    // terminal statuses are written only by the protocol's three exits (registry write interface,
    // authenticated by the protocol PDA — see charter.rs); the protocol's instruction surface is
    // pinned so no other exit can appear unreviewed
    let surface: Vec<String> = idl("merces_protocol")["instructions"]
        .as_array()
        .unwrap()
        .iter()
        .map(|i| i["name"].as_str().unwrap().to_string())
        .collect();
    let path = format!(
        "{}/fixtures/instruction_surface.json",
        env!("CARGO_MANIFEST_DIR")
    );
    let expected: Vec<String> =
        serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    assert_eq!(
        surface, expected,
        "protocol instruction surface changed: review against C11 and update the fixture"
    );
}

/// C11 §6: extinguishment needs two distinct registered attestors; then all claims end, the
/// unreleased treasury goes to holders pro rata with no fee and the estate keeps what had vested.
#[test]
fn c11_6_extinguishment_needs_two_distinct_attestors() {
    let v = vector("01_happy_path.json");
    let first_pay = step_index(&v, "pay", 0);
    let mut r = Runner::run_value(v.clone(), Some(first_pay));
    let s1 = r.series_pubkey("S1").unwrap();
    let call = |a: &str, b: &str| json!({"op": "extinguish", "series": "S1", "attestors": [a, b]});
    assert_code(
        r.exec_call(&call("attestor1", "attestor1")),
        u32::from(ProtocolError::AttestorsNotDistinct),
        "same attestor twice",
    );
    // a report-verifier key is not an attestor
    assert_code(
        r.exec_call(&call("attestor1", "verifier1")),
        u32::from(ProtocolError::KeyAccountMismatch),
        "verifier key as attestor",
    );
    let p = pdas(s1);
    let t = r.env.treasury(&s1).unwrap();
    let treasury_before = r.env.token_balance(&p.treasury_token);
    let vault_before = r.env.token_balance(&p.vault_token);
    r.exec_call(&call("attestor1", "attestor2")).unwrap();
    let l = r.env.ledger(&s1).unwrap();
    assert_eq!(l.stored_status() as u8, 6, "Extinguished");
    assert_eq!(l.open_due_amount, 0);
    assert_eq!(l.trueup_due, 0);
    let unreleased = treasury_before - r.env.token_balance(&p.treasury_token);
    assert_eq!(
        r.env.token_balance(&p.vault_token),
        vault_before + unreleased
    );
    let vested = t.proceeds - unreleased;
    assert!(
        vested >= t.released_total,
        "the estate keeps the vested part"
    );
    // a second extinguishment is refused; reports end
    assert_code(
        r.exec_call(&call("attestor1", "attestor2")),
        u32::from(ProtocolError::TerminalStatus),
        "already extinguished",
    );
    // every holder's final claim pays its pro-rata share and burns its units; nothing is left owed
    let mut paid = 0u64;
    let usdc = r.env.usdc;
    for name in ["b1", "b2", "b3", "b4"] {
        let w = r.actor_pubkey(name).unwrap();
        let before = r.env.balance_of(&w, &usdc);
        r.env.claim_final(&s1, &w).unwrap();
        paid += r.env.balance_of(&w, &usdc) - before;
        assert_eq!(r.env.token_balance(&ata(&w, &p.unit_mint, &TOKEN_2022)), 0);
    }
    assert_eq!(r.env.mint_supply(&p.unit_mint), 0);
    let left = r.env.token_balance(&p.vault_token);
    assert!(left < 4, "only WAD dust may stay in the vault, {left} left");
    assert_eq!(paid + left, vault_before + unreleased);
    let _ = DAY;
    let _ = Pubkey::default();
}

/// C11 §7: charter-relevant fields have no upgrade path — the registry exposes no setter for a
/// frozen field, `set_contract_hash` is Draft-only, `amend_terms` only lowers the cap with an
/// attestor's signature, and every vector replay re-checks the frozen block byte for byte
/// (`Runner::check_charter`). The registry is deployed with its upgrade authority revoked
/// (`solana/scripts/deploy.sh`).
#[test]
fn c11_7_charter_fields_have_no_upgrade_path() {
    // registry instructions that can write a Series
    let mut writers: BTreeSet<String> = BTreeSet::new();
    for ix in idl("merces_registry")["instructions"].as_array().unwrap() {
        if ix["accounts"]
            .as_array()
            .unwrap()
            .iter()
            .any(|a| a["name"] == "series" && a["writable"].as_bool().unwrap_or(false))
        {
            writers.insert(ix["name"].as_str().unwrap().to_string());
        }
    }
    let expected: BTreeSet<String> = [
        "amend_terms",
        "create_series",
        "mark_curve_activated",
        "mark_mint_finalized",
        "mark_raise_opened",
        "mark_raise_result",
        "mark_terminal",
        "set_contract_hash",
    ]
    .iter()
    .map(|s| s.to_string())
    .collect();
    assert_eq!(writers, expected);
    let v = vector("14_amendment.json");
    let opened = step_index(&v, "open_raise", 0);
    let mut r = Runner::run_value(v.clone(), Some(opened));
    let s1 = r.series_pubkey("S1").unwrap();
    let issuer = r.actor_keypair("issuer");
    expect_code(
        r.env.set_contract_hash(&issuer, &s1, [9u8; 32]),
        u32::from(RegistryError::NotDraft),
        "contract hash after opening",
    );
    let cap = r.env.series(&s1).cap_multiple_wad;
    let tc = format!("0x{}", hex::encode(r.env.series(&s1).terms_commitment));
    let raise_cap = json!({
        "op": "amend_terms", "actor": "issuer", "series": "S1",
        "newTermsCommitment": tc, "newCapMultipleWad": (cap + 1).to_string(), "attestor": "attestor1"
    });
    assert_code(
        r.exec_call(&raise_cap),
        u32::from(RegistryError::CapMultipleIncrease),
        "cap raised",
    );
    // full lifecycles with the byte-level charter check on every step
    run_vector("14_amendment.json");
    run_vector("06_redemption_terms.json");
    run_vector("11_extinguishment.json");
}
